package com.lyra.studio; import android.app.Activity; import android.view.WindowManager; import com.google.appinventor.components.annotations.*; import com.google.appinventor.components.common.*; import com.google.appinventor.components.runtime.*; @DesignerComponent(version = 1, description = "Extensao que adapta a tela para o teclado virtual nao cobrir o conteudo do Webviewer.", category = ComponentCategory.EXTENSION, nonVisible = true, iconName = "images/extension.png") @SimpleObject(external = true) public class KeyboardAdaptiveWebViewer extends AndroidNonvisibleComponent { private Activity activity; /* Construtor que inicializa o contexto da atividade */ public KeyboardAdaptiveWebViewer(ComponentContainer container) { super(container.$form()); this.activity = container.$context(); } @SimpleFunction(description = "Ativa o modo adjustResize para evitar que o teclado cubra o WebViewer.") public void EnableKeyboardAdaptation() { activity.runOnUiThread(new Runnable() { @Override public void run() { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); } }); } @SimpleFunction(description = "Desativa a adaptacao e retorna ao modo padrao.") public void DisableKeyboardAdaptation() { activity.runOnUiThread(new Runnable() { @Override public void run() { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_PAN); } }); } }